<?php
declare(strict_types=1);
namespace App\Infrastructure\Persistence\Doctrine\Taxonomy;
use App\Domain\Taxonomy\Repository\TaxonomySubjectMergeApplierInterface;use App\Infrastructure\Persistence\Doctrine\QuestionBank\Entity\QuestionTaxonomySubjectRecord;use App\Infrastructure\Persistence\Doctrine\Taxonomy\Entity\TaxonomySubjectAliasRecord;use Doctrine\ORM\EntityManagerInterface;
final class DoctrineTaxonomySubjectMergeApplier implements TaxonomySubjectMergeApplierInterface { public function __construct(private readonly EntityManagerInterface $entityManager){} public function reassignCanonicalReferences(string $sourceSubjectId,string $targetSubjectId):void{$this->entityManager->createQueryBuilder()->delete(QuestionTaxonomySubjectRecord::class,'source')->where('source.taxonomySubjectId=:source')->andWhere('source.questionId IN (SELECT target.questionId FROM '.QuestionTaxonomySubjectRecord::class.' target WHERE target.taxonomySubjectId=:target)')->setParameter('source',$sourceSubjectId)->setParameter('target',$targetSubjectId)->getQuery()->execute();$this->entityManager->createQueryBuilder()->update(QuestionTaxonomySubjectRecord::class,'assignment')->set('assignment.taxonomySubjectId',':target')->where('assignment.taxonomySubjectId=:source')->setParameter('source',$sourceSubjectId)->setParameter('target',$targetSubjectId)->getQuery()->execute();$this->entityManager->createQueryBuilder()->update(TaxonomySubjectAliasRecord::class,'alias')->set('alias.subjectId',':target')->where('alias.subjectId=:source')->setParameter('source',$sourceSubjectId)->setParameter('target',$targetSubjectId)->getQuery()->execute();} }
